    34→// ProcessEpoch describes the per epoch operations that are performed on the beacon state.
    35→// It's optimized by pre computing validator attested info and epoch total/attested balances upfront.
    36→//
    37→// Spec definition:
    38→//
    39→//	def process_epoch(state: BeaconState) -> None:
    40→//	    process_justification_and_finalization(state)
    41→//	    process_inactivity_updates(state)
    42→//	    process_rewards_and_penalties(state)
    43→//	    process_registry_updates(state)  # [Modified in Electra:EIP7251]
    44→//	    process_slashings(state)  # [Modified in Electra:EIP7251]
    45→//	    process_eth1_data_reset(state)
    46→//	    process_pending_deposits(state)  # [New in Electra:EIP7251]
    47→//	    process_pending_consolidations(state)  # [New in Electra:EIP7251]
    48→//	    process_effective_balance_updates(state)  # [Modified in Electra:EIP7251]
    49→//	    process_slashings_reset(state)
    50→//	    process_randao_mixes_reset(state)
    51→//	    process_historical_summaries_update(state)
    52→//	    process_participation_flag_updates(state)
    53→//	    process_sync_committee_updates(state)
    54→func ProcessEpoch(ctx context.Context, state state.BeaconState) error {
    55→	_, span := trace.StartSpan(ctx, "electra.ProcessEpoch")
    56→	defer span.End()
    57→
    58→	if state == nil || state.IsNil() {
    59→		return errors.New("nil state")
    60→	}
    61→	vp, bp, err := InitializePrecomputeValidators(ctx, state)
    62→	if err != nil {
    63→		return err
    64→	}
    65→	vp, bp, err = ProcessEpochParticipation(ctx, state, bp, vp)
    66→	if err != nil {
    67→		return err
    68→	}
    69→	state, err = precompute.ProcessJustificationAndFinalizationPreCompute(state, bp)
    70→	if err != nil {
    71→		return errors.Wrap(err, "could not process justification")
    72→	}
    73→	state, vp, err = ProcessInactivityScores(ctx, state, vp)
    74→	if err != nil {
    75→		return errors.Wrap(err, "could not process inactivity updates")
    76→	}
    77→	state, err = ProcessRewardsAndPenaltiesPrecompute(state, bp, vp)
    78→	if err != nil {
